import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
version = json.loads((root / "version.json").read_text(encoding="utf-8"))
print("- Добавлен CSQTT на основе оригинального клиента amurcanov 2.1.9 с протоколом CSQTT-WIRE-3. Отдельный транспорт передаёт IP-пакеты локальному SOCKS-адаптеру; TUN, DNS и маршрутизацией управляет ядро Throne.")
print("- Добавлены редактор профиля CSQTT, выбор TURN UDP или TCP/TLS, авторизация VK, обработка капчи и маскировка audio/video. Выбранный транспорт отображается в названии типа: CSQTT (UDP) или CSQTT (TCP).")
print("- Поддерживаются ссылки csqtt://connect?v=2 из lucx-ui и старые ссылки CSQTT. При импорте сохраняются первые шесть хешей; список потоков содержит значения, кратные 9, до 27 на хеш и не более 126 всего.")
print("- Проверки CSQTT используют отдельные процессы и конфигурации. Ручная проверка может открыть компактное окно капчи; фоновые проверки выполняются без окон. Выключение TUN останавливает профиль и его транспорт.")
print("- Пароли и хеши передаются транспорту через приватную конфигурацию. Вместе с транспортом поставляются его лицензия, сведения об исходной версии и исходники с изменениями интерфейса запуска.")
print()
print(f"Основа: Throne {version['throne_version']}, ветка dev, коммит [{version['throne_commit'][:8]}](https://github.com/throneproj/Throne/commit/{version['throne_commit']}).")
